func operationValue(operation *AgentOperationModel, field string) string {
	if operation == nil {
		return ""
	}
	switch field {
	case "charter":
		return operation.Charter
	case "fixture":
		return operation.Fixture
	case "fleet":
		return operation.FleetID
	case "source":
		return operation.SourceID
	}
	return ""
}

