func credentialOperationTitle(operation string) string {
	switch operation {
	case "create":
		return "Create credential"
	case "rotate":
		return "Rotate credential"
	case "revoke":
		return "Revoke credential"
	case "bind":
		return "Create exact binding"
	case "backup":
		return "Create policy-constrained backup"
	}
	return "Credential operation denied"
}

